  {
   "@type": "Question",
   "name": "Are they kicking to cover their poop?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Mostly not. Covering the poop is rare; it's closer to a marking behavior that leaves scent and scratch marks."
   }
  },
  {
   "@type": "Question",
   "name": "Should I stop my dog from kicking after pooping?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "It's natural behavior, so in most cases you don't need to stop it. Only gently redirect them with the leash when they're tearing up someone's flower bed or the ground is unsafe."
   }
  },
  {
   "@type": "Question",
   "name": "My dog never kicks. Is that okay?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. Lots of dogs don't kick. It depends on personality and habit."
   }
